import React, { useState, useEffect } from 'react';
import {
    Button, Box, AppBar, Toolbar, TextField, Table, TableBody, TableCell,
    TableContainer, Menu, TableHead, TableRow, Paper, IconButton, Typography,
    MenuItem, Select, FormControl, InputLabel, Dialog, DialogTitle,
    DialogContent, DialogActions
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import { useNavigate } from 'react-router-dom';
import AddIcon from '@mui/icons-material/Add';
import Fab from '@mui/material/Fab';
import FirstComponent from './datapicker';

const API_SUB_URL = 'http://localhost:5000/subcategories';
const API_CAT_URL = 'http://localhost:5000/categories';
const API_DATE_URL = 'http://localhost:5000/dates';

export default function Dates() {
    const navigate = useNavigate();

    const [categories, setCategories] = useState([]);
    const [allSubCategories, setAllSubCategories] = useState([]);
    const [dates, setDates] = useState([]);
    const [selectedDate, setSelectedDate] = useState(null);
    const [todolist, setTodolist] = useState([]);
    const [todoName, setTodoName] = useState('');

    // Creation States
    const [selectedCatId, setSelectedCatId] = useState('');
    const [selectedSubId, setSelectedSubId] = useState('');

    // Dialog / Modal Editing States
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const [editingId, setEditingId] = useState(null);
    const [editDate, setEditDate] = useState('');

    const [dashboardAnchor, setDashboardAnchor] = useState(null);
    const isDashboardOpen = Boolean(dashboardAnchor);

    // 1. Fetch data on component mount
    useEffect(() => {
        fetch(API_CAT_URL).then(res => res.json()).then(data => setCategories(Array.isArray(data) ? data : []));
        fetch(API_SUB_URL).then(res => res.json()).then(data => setAllSubCategories(Array.isArray(data) ? data : []));
        fetch(API_DATE_URL).then(res => res.json()).then(data => setDates(Array.isArray(data) ? data : []));
    }, []);

    // 3. UPDATE: Open dialog and populate fields
    const openEditDialog = (item) => {
        setEditingId(item._id || item.id);
        // Fallback to existing date field string if present
        setEditDate(item.date ? new Date(item.date).toISOString().split('T')[0] : '');
        setIsDialogOpen(true);
    };

    const closeEditDialog = () => {
        setIsDialogOpen(false);
        setEditingId(null);
        setEditDate(''); // FIXED: Removed undefined product status clear calls
    };

    // Save changes from Dialog to DB
    const handleUpdateProduct = async () => {
        if (!editDate.trim()) return;
        try {
            const response = await fetch(`${API_DATE_URL}/${editingId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ date: editDate })
            });

            if (response.ok) {
                const refreshRes = await fetch(API_DATE_URL);
                const updatedProds = await refreshRes.json();
                setDates(Array.isArray(updatedProds) ? updatedProds : []);
                closeEditDialog();
            }
        } catch (err) {
            console.error(err);
        }
    };

    // 4. DELETE: Remove document from DB
    const handleDeleteProduct = async (id) => {
        try {
            const response = await fetch(`${API_DATE_URL}/${id}`, { method: 'DELETE' });
            if (response.ok) {
                setDates(dates.filter(p => p._id !== id && p.id !== id));
            }
        } catch (err) {
            console.error(err);
        }
    };

    const filteredSubCategories = allSubCategories.filter(sub => {
        const parentId = sub.category?._id || sub.category?.id;
        return parentId === selectedCatId;
    });

    const handleBulkSubmit = async () => {
        if (todolist.length === 0) return;

        try {
            // Map over every item in your Todo Items staging list to create an array of fetch promises
            const savePromises = todolist.map(item =>
                fetch(API_DATE_URL, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        date: item.date,
                        subCategoryId: item.subCategoryId
                    })
                })
            );

            // Wait until ALL database insert operations have successfully finished
            await Promise.all(savePromises);

            // Fetch the fresh list from the database to update the bottom "Grouped with Data" table
            const refreshRes = await fetch(API_DATE_URL);
            const updatedData = await refreshRes.json();
            setDates(Array.isArray(updatedData) ? updatedData : []);

            // Clear out the temporary Todo Items panel
            setTodolist([]);
        } catch (err) {
            console.error("Error during bulk submission:", err);
        }
    };

    const handleAddListItem = async () => {
        if (!selectedSubId) return;

        // Find the name strings from your loaded lists to display them in the local list view

        const mainCatName = categories.find(c => (c.id || c._id) === selectedCatId)?.name || "";
        const subCatName = allSubCategories.find(s => (s.id || s._id) === selectedSubId)?.name || "";
        const newStagedItem = {
            // Create a temporary unique ID for rendering keys
            localId: Date.now(),
            date: selectedDate ? selectedDate.toDate() : new Date(),
            subCategoryId: selectedSubId,
            subCategoryName: subCatName,
            categoryName: mainCatName,
            todoName: todoName
        };

        // Add to our local staging array
        setTodolist([...todolist, newStagedItem]);

        // Reset inputs so the user can add another one
        setSelectedCatId('');
        setSelectedSubId('');
        setSelectedDate(null);
        setTodoName('');
    };

    const handleClearlist = () => {
        setSelectedCatId('');
        setSelectedSubId('');
        setSelectedDate(null);
        setTodolist([]);
        setTodoName('');
    }

    return (
        <Box sx={{ flexGrow: 1, p: 3 }}>
            {/* Navbar */}
            <AppBar position="static" sx={{ mb: 4 }}>
                <Toolbar sx={{ gap: 2 }}>
                    <Box onMouseLeave={() => setDashboardAnchor(null)}>
                        <Button
                            id="dashboard-button" color="inherit"
                            onMouseEnter={(e) => setDashboardAnchor(e.currentTarget)}
                        >
                            Dates
                        </Button>
                        <Menu
                            anchorEl={dashboardAnchor} open={isDashboardOpen} onClose={() => setDashboardAnchor(null)}
                            MenuListProps={{ onMouseEnter: () => setDashboardAnchor(document.getElementById('dashboard-button')), onMouseLeave: () => setDashboardAnchor(null) }}
                        >
                            <MenuItem onClick={() => { setDashboardAnchor(null); navigate('/dashboard'); }}>View Categories</MenuItem>
                            <MenuItem onClick={() => { setDashboardAnchor(null); navigate('/subcategories'); }}>View Sub Categories</MenuItem>
                            <MenuItem onClick={() => { setDashboardAnchor(null); navigate('/products'); }}>View Grouping</MenuItem>
                        </Menu>
                    </Box>
                </Toolbar>
            </AppBar>

            <Typography variant="h4" sx={{ mb: 5 }}> Dates</Typography>

            {/* CASCADING DROPDOWNS FORM */}
            <Box>
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 3, mb: 5, alignItems: 'center' }}>
                    <TextField
                        label="Name"
                        variant="outlined"
                        size="large"
                        sx={{ width: '40%' }}
                        value={todoName}
                        onChange={(e) => setTodoName(e.target.value)}
                    />
                    <FormControl size="large" sx={{ minWidth: 250 }}>
                        <InputLabel id="main-cat-label">1. Select Main Category</InputLabel>
                        <Select
                            labelId="main-cat-label" value={selectedCatId} label="1. Select Main Category"
                            onChange={(e) => { setSelectedCatId(e.target.value); setSelectedSubId(''); }}
                        >
                            {categories.map((cat) => (
                                <MenuItem key={cat.id || cat._id} value={cat.id || cat._id}>{cat.name}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>

                    <FormControl size="large" sx={{ minWidth: 250 }} disabled={!selectedCatId} >
                        <InputLabel id="dependent-sub-label">2. Select Subcategory</InputLabel>
                        <Select
                            labelId="dependent-sub-label" value={selectedSubId} label="2. Select Subcategory"
                            onChange={(e) => setSelectedSubId(e.target.value)}
                        >
                            {filteredSubCategories.map((sub) => (
                                <MenuItem key={sub._id || sub.id} value={sub._id || sub.id}>{sub.name}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <FormControl size="large" sx={{ minWidth: 250 }} disabled={!selectedSubId}>
                        <FirstComponent
                            value={selectedDate}
                            onChange={(newDate) => setSelectedDate(newDate)}
                            disabled={!selectedSubId}
                        />
                    </FormControl>

                    <Fab color="primary" aria-label="add" onClick={handleAddListItem} >
                        <AddIcon />
                    </Fab>
                    <Button
                        variant="contained"
                        color="primary"
                        onClick={handleBulkSubmit}
                        disabled={todolist.length === 0}
                    >
                        SUMBIT
                    </Button>
                    <Button variant="contained" color="error" size="large" onClick={handleClearlist}>
                        Clear
                    </Button>
                </Box>
            </Box>

            <Paper>

            </Paper>
            {todolist.length > 0 && (
                <Paper variant="outlined" sx={{ p: 2, mb: 4, backgroundColor: '#fafafa', width: '50%' }}>
                    <Typography variant="subtitle1" sx={{ mb: 1, fontWeight: 'bold' }}>
                        TODO ITEMS ({todolist.length})
                    </Typography>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                        {todolist.map(item => (
                            <Box
                                key={item.localId}
                                sx={{
                                    display: 'flex',
                                    justifyContent: 'space-between',
                                    py: 1,
                                    mr: 2,

                                    width: '100%'
                                }}
                            >
                                <Typography variant="body2">
                                    {item.todoName}
                                </Typography>

                                <Typography variant="body2">
                                    {item.categoryName}
                                </Typography>
                                <Typography variant="body2">
                                    {item.subCategoryName}
                                </Typography>
                                <Typography variant="body2" sx={{ fontWeight: 'bold' }}>
                                    {new Date(item.date).toLocaleDateString()}
                                </Typography>
                                <Box>
                                    <IconButton
                                        size="small"
                                        color="primary"

                                    >
                                        <EditIcon />
                                    </IconButton>

                                    <IconButton
                                        size="small"
                                        color="error"
                                        onClick={() => setTodolist(todolist.filter(i => i.localId !== item.localId))}
                                    >
                                        <DeleteIcon />
                                    </IconButton>
                                </Box>
                            </Box>
                        ))}
                    </Box>
                </Paper>
            )}


            {/* RENDER DATA TABLE */}
            <Typography variant="h5" sx={{ mb: 2 }}>Grouped with Data </Typography>
            <TableContainer component={Paper}>
                <Table>
                    <TableHead>
                        <TableRow sx={{ backgroundColor: '#f5f5f5' }}>
                            <TableCell><strong>ID</strong></TableCell>
                            <TableCell><strong>Main Category</strong></TableCell>
                            <TableCell><strong>Sub Category</strong></TableCell>
                            <TableCell><strong>Date</strong></TableCell>
                            <TableCell align="right"><strong>Action</strong></TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {/* FIXED: Protected array checking mapping layout with clean text-node formatting layout closures */}
                        {Array.isArray(dates) && dates.map((prod, index) => {
                            const pId = prod._id || prod.id;
                            return (
                                <TableRow key={pId}>
                                    <TableCell>{index + 1}</TableCell>
                                    <TableCell>
                                        {prod.subCategory?.category?.name || "Unassigned"}
                                    </TableCell>
                                    <TableCell style={{ fontWeight: 500 }}>
                                        {prod.subCategory?.name || "Unassigned"}
                                    </TableCell>
                                    <TableCell>
                                        {prod.date ? new Date(prod.date).toLocaleDateString() : "No Date Specified"}
                                    </TableCell>
                                    <TableCell align="right">
                                        <IconButton color="primary" onClick={() => openEditDialog(prod)}>
                                            <EditIcon />
                                        </IconButton>
                                        <IconButton color="error" onClick={() => handleDeleteProduct(pId)}>
                                            <DeleteIcon />
                                        </IconButton>
                                    </TableCell>
                                </TableRow>
                            );
                        })}
                        {(!dates || dates.length === 0) && (
                            <TableRow>
                                <TableCell colSpan={5} align="center">No grouped items configured.</TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </TableContainer>

            {/* EDITING DIALOG MODAL */}
            <Dialog open={isDialogOpen} onClose={closeEditDialog} fullWidth maxWidth="xs">
                <DialogTitle>Edit Date Entry</DialogTitle>
                <DialogContent sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
                    <TextField
                        sx={{ mt: 2 }}
                        type="date"
                        variant="outlined"
                        fullWidth
                        size='large'
                        value={editDate}
                        onChange={(e) => setEditDate(e.target.value)}
                    />
                </DialogContent>
                <DialogActions sx={{ p: 2, pt: 0 }}>
                    <Button onClick={closeEditDialog} color="inherit">
                        Cancel
                    </Button>
                    <Button
                        onClick={handleUpdateProduct}
                        variant="contained"
                        disabled={!editDate.trim()}
                    >
                        Save
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
}